          expect p, tkSemiColon
          if (p.tok.kind in Tk8):
            pushIndAny p
            pSemiStmtList p
            popInd p
          pOptPar p
          expect p, tkParRi
          wrap p, m0, "stmts"
        elif (p.tok.kind in {tkColon}):
