    wrap p, m0, "func"
  elif (p.tok.kind in {tkIterator}):
    expect p, tkIterator
    pParamListColon p
    if (p.tok.kind in {tkCurlyDotLe}):
      pPragma p
    if (p.tok.kind in {tkEquals}):
