  elif ((p.tok.kind in Tk4 and indClass(p) in {icNoInd, icGt})) and typeOperandFollows(p):
    pValidInd p
    pPrimary(p, mode)
  else:
    error p, "expected typeKAuxOperand"
  discardUnused m0

proc pTypeDescExpr*(p: var Parser) =
