proc pPrimary*(p: var Parser; mode: PrimaryMode) =
  let m0 = mark(p)
  if (p.tok.kind in Tk5):
    pSimplePrimary(p, mode)
  elif ((p.tok.kind in Tk6)) and isSigilLike(p):
    pPrefixOperator p
    let m52 = mark(p)
    if (p.tok.kind in Tk5):
      pSimplePrimary(p, mode)
    else:
      pPrimary(p, pmNormal)
    discardUnused m52
    wrap p, m0, "prefix"
  elif ((p.tok.kind in Tk6)) and isUnary(p):
    pOperatorB p
    pPrimary(p, mode)
    wrap p, m0, "prefix"
  elif (p.tok.kind in {tkFunc, tkIterator, tkProc}):
    pRoutineExpr p
  elif (p.tok.kind in {tkBind}):
    expect p, tkBind
    pOptInd p
    pPrimary(p, pmNormal)
    wrap p, m0, "bind"
  elif (p.tok.kind in Tk7):
    pTypeDescKeyw(p, mode)
  elif (p.tok.kind in Tk6):
    pPrefixOperator p
    pPrimary(p, mode)
    wrap p, m0, "prefix"
  else:
    error p, "expected primary"
  discardUnused m0

proc pSimpleExpr*(p: var Parser; limit: int, mode: PrimaryMode) =
  let m0 = mark(p)
  pPrimaryPragma(p, mode)
  var prec = getPrecedence(p)
  while prec >= limit and indClass(p) == icNoInd:
    let assoc = (if isRightAssoc(p): 0 else: 1)
    insertLeafAt p, m0, p.tok.s
    getTok p
    pSimpleExpr(p, prec + assoc, mode)
    wrap p, m0, "infix"
    prec = getPrecedence(p)
  discardUnused m0

proc pPrimaryPragma*(p: var Parser; mode: PrimaryMode) =
  let m0 = mark(p)
  pPrimary(p, mode)
  if ((p.tok.kind in {tkCurlyDotLe} and indClass(p) in {icNoInd, icGt})) and pragmaOnPrimary(p, mode):
    pValidInd p
    pPragma p
    wrap p, m0, "pragmax"
  discardUnused m0

proc pExtraPostExprBlock*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk14 and indClass(p) in {icEq}):
    checkInd p, {icEq}
    if (p.tok.kind in {tkDo}):
      pDoBlock p
    elif (p.tok.kind in {tkOf}):
      expect p, tkOf
