        insertLeafAt p, m0, p.tok.s
        getTok p
        pSimpleExpr(p, prec98 + assoc98, pmNormal)
        wrap p, m0, "infix"
        prec98 = getPrecedence(p)
      if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
        pPostExprBlocks p
    else:
      error p, "expected complexOrSimpleStmt"
  elif (p.tok.kind in {tkConst}):
    expect p, tkConst
    pSection_constant p
  elif (p.tok.kind in {tkLet}):
    expect p, tkLet
    pSection_variable p
  elif (p.tok.kind in {tkVar}):
    expect p, tkVar
    pSection_variable p
  elif (p.tok.kind in {tkUsing}):
    expect p, tkUsing
    pSection_variable p
  else:
    pSimpleStmt p
  discardUnused m0

